//! Hermetica API client. Generated by scripts/gen-sdks.mjs; the operations live in operations.rs.
mod operations;

use serde_json::Value;
use std::collections::BTreeMap;
use std::fmt;
use std::time::Duration;

/// Any non-2xx answer, or a network error (status 0).
#[derive(Debug, Clone, PartialEq)]
pub struct Error {
    pub status: u16,
    pub code: String,
    pub message: String,
    pub details: Value,
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{} {}: {}", self.status, self.code, self.message)
    }
}

impl std::error::Error for Error {}

/// The inputs of one call: path params, query params, a JSON body and an optional Idempotency-Key.
#[derive(Debug, Default, Clone)]
pub struct Params {
    pub path: BTreeMap<String, String>,
    pub query: BTreeMap<String, String>,
    pub body: Option<Value>,
    pub idempotency_key: Option<String>,
}

impl Params {
    pub fn new() -> Self {
        Self::default()
    }
    pub fn path(mut self, k: impl Into<String>, v: impl ToString) -> Self {
        self.path.insert(k.into(), v.to_string());
        self
    }
    pub fn query(mut self, k: impl Into<String>, v: impl ToString) -> Self {
        self.query.insert(k.into(), v.to_string());
        self
    }
    pub fn body(mut self, v: Value) -> Self {
        self.body = Some(v);
        self
    }
    pub fn idempotency_key(mut self, k: impl Into<String>) -> Self {
        self.idempotency_key = Some(k.into());
        self
    }
}

/// Thread-safe; clone it freely (the HTTP connection pool is shared).
#[derive(Clone)]
pub struct Client {
    api_key: String,
    base_url: String,
    /// Sent as X-Workspace-Id when set.
    pub workspace_id: Option<String>,
    /// How many times a network error, 429 or 5xx is retried after the first attempt; 0 turns retries off.
    pub max_retries: u32,
    http: reqwest::Client,
}

fn encode(s: &str) -> String {
    s.bytes()
        .map(|b| match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => (b as char).to_string(),
            _ => format!("%{:02X}", b),
        })
        .collect()
}

/// Full jitter: a random wait up to 250ms * 2^attempt, capped at 8s.
fn backoff(attempt: u32) -> Duration {
    use std::hash::{BuildHasher, Hasher};
    let ceiling: u64 = if attempt < 5 { 250 << attempt } else { 8000 };
    let mut h = std::collections::hash_map::RandomState::new().build_hasher();
    h.write_u32(attempt);
    Duration::from_millis(h.finish() % ceiling)
}

/// Retry-After in delta-seconds; an HTTP-date (rare from this API) falls back to the backoff.
fn retry_after(v: Option<&reqwest::header::HeaderValue>) -> Option<Duration> {
    let secs: f64 = v?.to_str().ok()?.trim().parse().ok()?;
    (secs >= 0.0 && secs < 1e6).then(|| Duration::from_secs_f64(secs))
}

impl Client {
    pub fn new(api_key: impl Into<String>, base_url: impl Into<String>) -> Self {
        let http = reqwest::Client::builder().timeout(Duration::from_secs(30)).build().expect("reqwest client");
        Self::with_http(api_key, base_url, http)
    }

    /// Bring your own reqwest client (proxies, timeouts, TLS settings).
    pub fn with_http(api_key: impl Into<String>, base_url: impl Into<String>, http: reqwest::Client) -> Self {
        Self { api_key: api_key.into(), base_url: base_url.into().trim_end_matches('/').to_string(), workspace_id: None, max_retries: 3, http }
    }

    fn url(&self, path: &str, p: &Params) -> Result<String, Error> {
        let mut out = String::new();
        let mut rest = path;
        while let Some(i) = rest.find('{') {
            let j = rest[i..].find('}').map(|j| i + j).unwrap_or(rest.len());
            let name = &rest[i + 1..j];
            let v = p.path.get(name).ok_or_else(|| Error { status: 0, code: "invalid".into(), message: format!("missing path param {}", name), details: Value::Null })?;
            out.push_str(&rest[..i]);
            out.push_str(&encode(v));
            rest = rest.get(j + 1..).unwrap_or("");
        }
        out.push_str(rest);
        let q: Vec<String> = p.query.iter().map(|(k, v)| format!("{}={}", encode(k), encode(v))).collect();
        Ok(format!("{}{}{}", self.base_url, out, if q.is_empty() { String::new() } else { format!("?{}", q.join("&")) }))
    }

    /// Runs one operation and returns the parsed JSON answer (Null for an empty body).
    pub async fn request(&self, method: &str, path: &str, p: Params) -> Result<Value, Error> {
        let url = self.url(path, &p)?;
        let m = reqwest::Method::from_bytes(method.as_bytes()).map_err(|e| Error { status: 0, code: "invalid".into(), message: e.to_string(), details: Value::Null })?;
        // A retry with the same key never repeats the action: every attempt of a non-GET carries it.
        let key = if method == "GET" { None } else { Some(p.idempotency_key.clone().unwrap_or_else(|| uuid::Uuid::new_v4().to_string())) };
        let mut attempt = 0;
        loop {
            let mut req = self.http.request(m.clone(), &url).bearer_auth(&self.api_key).header("Accept", "application/json");
            if let Some(ws) = &self.workspace_id {
                req = req.header("X-Workspace-Id", ws);
            }
            if let Some(k) = &key {
                req = req.header("Idempotency-Key", k);
            }
            if let Some(b) = &p.body {
                req = req.json(b);
            }
            match req.send().await {
                Err(e) => {
                    if attempt >= self.max_retries {
                        return Err(Error { status: 0, code: "network_error".into(), message: e.to_string(), details: Value::Null });
                    }
                    tokio::time::sleep(backoff(attempt)).await;
                }
                Ok(res) => {
                    let status = res.status().as_u16();
                    if (status == 429 || status >= 500) && attempt < self.max_retries {
                        tokio::time::sleep(retry_after(res.headers().get("Retry-After")).unwrap_or_else(|| backoff(attempt))).await;
                    } else {
                        let text = res.text().await.unwrap_or_default();
                        return decode(status, &text);
                    }
                }
            }
            attempt += 1;
        }
    }

    /// Every item of a list operation, following nextCursor.
    pub async fn list_all(&self, method: &str, path: &str, mut p: Params) -> Result<Vec<Value>, Error> {
        let mut all = Vec::new();
        loop {
            let page = self.request(method, path, p.clone()).await?;
            if let Some(items) = page.get("items").and_then(Value::as_array) {
                all.extend(items.iter().cloned());
            }
            match page.get("nextCursor").and_then(Value::as_str) {
                Some(c) if !c.is_empty() => {
                    p.query.insert("cursor".into(), c.to_string());
                }
                _ => return Ok(all),
            }
        }
    }
}

fn decode(status: u16, text: &str) -> Result<Value, Error> {
    let v: Value = if text.is_empty() { Value::Null } else { serde_json::from_str(text).unwrap_or(Value::Null) };
    if status < 300 {
        return Ok(v);
    }
    let e = v.get("error");
    let s = |k: &str| e.and_then(|e| e.get(k)).and_then(Value::as_str).map(str::to_string);
    Err(Error {
        status,
        code: s("code").unwrap_or_else(|| "http_error".into()),
        message: s("message").unwrap_or_else(|| text.trim().to_string()),
        details: e.and_then(|e| e.get("details")).cloned().unwrap_or(Value::Null),
    })
}
